import { useSelectedLayoutSegment } from 'next/navigation'

export default function NavTabs() {
  const segment = useSelectedLayoutSegment()

  return (
    <nav aria-label="Sections">
      {['overview', 'settings'].map((slug) => (
        <a
          key={slug}
          href={`/${slug}`}
          aria-current={segment === slug ? 'page' : undefined}
        >
          {slug}
        </a>
      ))}
    </nav>
  )
}

'use client'

import { useSelectedLayoutSegments } from 'next/navigation'

export default function Breadcrumbs() {
  const segments = useSelectedLayoutSegments()

  return (
    <nav aria-label="Breadcrumb">
      {segments.map((segment, index) => (
        <span key={`${segment}-${index}`}>
          {index > 0 && ' / '}{segment}
        </span>
      ))}
    </nav>
  )
}

'use client'

import { useServerInsertedHTML } from 'next/navigation'
import { useState } from 'react'

export default function StyleRegistry({ children }: { children: React.ReactNode }) {
  const [styles] = useState(() => new Set<string>())

  useServerInsertedHTML(() => {
    const elements = [...styles].map((css) => <style key={css}>{css}</style>)
    styles.clear()
    return <>{elements}</>
  })

  return <>{children}</>
}

import type { Viewport } from 'next'

export const viewport: Viewport = {
  width: 'device-width',
  initialScale: 1,
  themeColor: '#ffffff',
}

export default function Page() {
  return <main>Responsive page</main>
}
